<script lang="ts">import {goto} from '$app/navigation';import {selectedRole} from '$lib/stores/app';const map:any={patient:'/app',family:'/app',doctor:'/dashboard',physicist:'/physics',therapist:'/dashboard',nurse:'/dashboard',admin:'/admin',manager:'/admin/analytics'};function enter(role:string){localStorage.setItem('selectedRole',role);selectedRole.set(role);goto(map[role]||'/');}</script>
<div class="max-w-3xl mx-auto p-6"><h1 class="text-3xl font-bold mb-4">Login Demo Role</h1><div class="grid md:grid-cols-4 gap-3">{#each Object.keys(map) as r}<button class="card p-4 hover:scale-[1.02] transition" on:click={()=>enter(r)}>Masuk sebagai {r}</button>{/each}</div></div>
